# -*- coding: utf-8 -*-
"""便携运行时引导：把 runtime/pkgs/<组> 作为附加 site 目录加载。

为什么不用 PYTHONPATH：
    pywin32 等包靠 site-packages 里的 .pth 文件注册 DLL 路径
    （pywin32.pth 里有 `import pywin32_bootstrap`），
    而 PYTHONPATH 加入的目录不会被 site 处理 .pth，会报 No module named 'pywintypes'。
    site.addsitedir() 会正确处理 .pth，所以统一走这里。

为什么按「组」隔离：
    gallerydl / xhs / mediacrawler 三组各自打包了同一批第三方库的不同版本
    （xhs 与 mediacrawler 都带 fastapi、pydantic、starlette…）。
    若一次性全挂到 sys.path，先挂的组会遮住后挂的组，xhs 引擎就会 import 到
    mediacrawler 的 fastapi 而崩掉。因此由调用方用环境变量 MD_PKG_GROUPS
    指定本次要用的组（如 "gallerydl" 或 "xhs"），互不干扰。

    MD_PKG_GROUPS 未设置时（手动调用、调试）挂载本运行时该管的全部组：
    mediacrawler 由 3.11 运行时（runtime/python311）专门负责，这里排除，
    否则它的 fastapi / pydantic 会遮住 xhs 的同名库。
"""
import os
import re
import site

_HERE = os.path.dirname(os.path.abspath(__file__))
_RUNTIME = os.path.dirname(os.path.dirname(os.path.dirname(_HERE)))
_PKGS = os.path.join(_RUNTIME, "pkgs")

# 属于 3.11 运行时的包组，本运行时（3.12）默认不挂
_NOT_MINE = {"mediacrawler"}

if os.path.isdir(_PKGS):
    _want = os.environ.get("MD_PKG_GROUPS", "").strip()
    if _want:
        _names = [n for n in re.split(r"[;,]", _want) if n.strip()]
    else:
        _names = [d for d in sorted(os.listdir(_PKGS)) if d not in _NOT_MINE]
    for _name in _names:
        _dir = os.path.join(_PKGS, _name.strip())
        if os.path.isdir(_dir):
            site.addsitedir(_dir)